contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We need to initialize c before calling setSlopes or rate. The InvMutTest contract is the deployer
    // of c according to the checker; however initialize expects an access control address. We pass
    // address(this) and rely on Access.checkAccess being called only on functions guarded by checkAccess;
    // setSlopes and setLimits are checkAccess-protected. To satisfy access checks, we will not call setLimits
    // (which also needs access). setSlopes is protected, but _authorizeUpgrade uses checkAccess(bytes4(0)) and
    // initialize only sets access control. For the purpose of this property we will focus on the behavior of
    // setSlopes: either it reverts due to InvalidKink or it succeeds. If it succeeds, then a subsequent rate
    // call for any vault/asset (we choose arbitrary addresses passed in) should not revert and should return
    // a uint256. The property asserts this relation between setSlopes reverting and rate reverting.

    // Single public entry point that the checker will call with arbitrary inputs.
    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 amount) public payable {
        require(true);

        // initialize c with this contract as access control. This call must be a top-level statement.
        // initialize is external and uses initializer modifier; safe to call once.
        c.initialize(address(this));

        // Build SlopeData abi-encoded to call setSlopes. We must call the external function directly.
        IVaultAdapter.SlopeData memory s = IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});

        bool setSlopesReverted;
        try c.setSlopes(asset, s) {
            setSlopesReverted = false;
        } catch {
            setSlopesReverted = true;
        }

        bool rateReverted;
        uint256 rateRet = 0;
        // Call rate and capture whether it reverts. rate is external and may read IVault; we just call it.
        try c.rate(vault, asset) returns (uint256 r) {
            rateReverted = false;
            rateRet = r;
        } catch {
            rateReverted = true;
        }

        // General rule asserted:
        // If setSlopes succeeded (didn't revert) then rate must not revert and must return a uint256 (we observe rateReverted==false).
        // If setSlopes reverted, no requirement on rate's behavior (it may or may not revert).
        assert((!setSlopesReverted) ? (rateReverted == false) : true);
    }

    // receive to accept any ETH if needed by external calls
    receive() external payable {}
}

