contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test that setSlopes enforces kink in (0, 1e27) and that successful setSlopes does not make subsequent rate call revert.
    // Inputs: asset - target asset address for slopes; kink, slope0, slope1 - slope parameters; vault, assetForRate - inputs to rate
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address vault, address assetForRate) public payable {
        // No precondition on parameters; we will observe whether setSlopes reverts.
        bool setSlopesReverted;
        // Prepare SlopeData ABI-encoded for call
        bytes memory data = abi.encode(kink, slope0, slope1);

        // Call setSlopes and capture whether it reverts. We must call the function as a top-level statement.
        // Because setSlopes is external and takes a struct, we call via try/catch on the contract method.
        try c.setSlopes(asset, C.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            setSlopesReverted = false;
        } catch {
            setSlopesReverted = true;
        }

        // Now attempt to call rate; capture whether rate reverts and any returned value if not.
        bool rateReverted;
        uint256 returnedRate = 0;
        try c.rate(vault, assetForRate) returns (uint256 r) {
            rateReverted = false;
            returnedRate = r;
        } catch {
            rateReverted = true;
        }

        // General rule (single assert):
        // If setSlopes reverted, then kink was invalid (kink == 0 or kink >= 1e27).
        // If setSlopes succeeded then rate must not revert (rate is always callable after successful slope set).
        // We express both implications in one boolean formula.
        assert(
            (
                setSlopesReverted && (kink == 0 || kink >= 1e27)
            ) || (
                !setSlopesReverted && !rateReverted
            )
        );
    }

    receive() external payable { }
}

