    constructor(C _c) { c = _c; }

    // Single public test function: ensures setSlopes does not revert for valid kink range
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        // Require the precondition that the contract enforces for kink
        require(kink > 0 && kink < 1e27);

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });

        bool reverted;
        try c.setSlopes(asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for all inputs satisfying the precondition, setSlopes must not revert
        assert(!reverted);
    }

    receive() external payable { }
}

