contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We use parameters to exercise both valid and invalid kink values and ensure behavior.
    // _vault and _asset are arbitrary addresses for rate queries; amount is unused but included
    // to follow the template (no Ether required).
    function run(address _asset, address _vault, uint256 _kink, uint256 _slope0, uint256 _slope1, uint256 amount) public payable {
        require(true);

        // Read some observable state before any change: call rate to potentially initialize utilizationData
        // We catch reverts but continue. We only use calls via c's external surface.
        bool beforeReverted;
        uint256 beforeRate;
        try c.rate(_vault, _asset) returns (uint256 r) {
            beforeReverted = false;
            beforeRate = r;
        } catch {
            beforeReverted = true;
            beforeRate = 0;
        }

        // Prepare slopes struct ABI-encoded for external call to setSlopes
        // Solidity can't construct the SlopeData type here because it's defined inside IVaultAdapter in the other unit.
        // But we may call c.setSlopes since it expects (address, SlopeData memory). We can construct via inline type via tuple.

        bool didRevert;
        // Attempt to call setSlopes with provided params; it will revert if kink==0 or kink>=1e27
        try c.setSlopes(_asset, ( _kink, _slope0, _slope1 )) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // After the call, query rate again to observe any change caused by setSlopes (or lack thereof).
        bool afterReverted;
        uint256 afterRate;
        try c.rate(_vault, _asset) returns (uint256 r2) {
            afterReverted = false;
            afterRate = r2;
        } catch {
            afterReverted = true;
            afterRate = 0;
        }

        // General rule asserted:
        // If setSlopes reverted because kink was invalid (kink==0 or kink>=1e27), then nothing observable via rate should have changed due to setSlopes: i.e., if before rate call did not revert then either after rate call also does not revert and equals beforeRate, or both calls revert.
        // Conversely, if setSlopes succeeded (didRevert == false), then kink was valid (0 < kink < 1e27) and afterwards either rate became callable (did not revert) — we assert at least that a successful setSlopes implies kink in valid range.

        bool kinkValid = (_kink != 0 && _kink < 1e27);

        // Build the final assertion combining both directions described above.
        assert(
            // If setSlopes reverted then kink must be invalid AND the observable rate did not change from before to after (unless both reverted)
            (didRevert ? (
                (!kinkValid) && (
                    (beforeReverted && afterReverted) || (!beforeReverted && !afterReverted && afterRate == beforeRate)
                )
            ) : (
                // If setSlopes succeeded then kink must be valid
                kinkValid
            ))
        );
    }

    receive() external payable { }
 }

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters to construct a SlopeData via ABI-encoded bytes and call setSlopes.
    // _asset and _vault are arbitrary addresses for rate queries.
    // _kink, _slope0, _slope1 are the slope struct fields.
    function run(address _asset, address _vault, uint256 _kink, uint256 _slope0, uint256 _slope1) public payable {
        require(true);

        // Observe rate before attempting to set slopes. Catch revert.
        bool beforeReverted;
        uint256 beforeRate;
        try c.rate(_vault, _asset) returns (uint256 r) {
            beforeReverted = false;
            beforeRate = r;
        } catch {
            beforeReverted = true;
            beforeRate = 0;
        }

        // Prepare calldata for setSlopes(address, SlopeData).
        // SlopeData is (uint256 kink, uint256 slope0, uint256 slope1) in that order.
        bytes memory data = abi.encodeWithSelector(
            c.setSlopes.selector,
            _asset,
            // encode the struct as a tuple matching the solidity ABI for the struct in memory
            (_kink, _slope0, _slope1)
        );

        // Perform low-level call to c to be able to catch success/failure and ensure we pass the struct layout correctly.
        bool callSucceeded;
        assembly {
            let ptr := add(data, 32)
            let len := mload(data)
            // perform call with all available gas, no value
            callSucceeded := call(gas(), address(c), 0, ptr, len, 0, 0)
        }

        // Observe rate after attempting to set slopes. Catch revert.
        bool afterReverted;
        uint256 afterRate;
        try c.rate(_vault, _asset) returns (uint256 r2) {
            afterReverted = false;
            afterRate = r2;
        } catch {
            afterReverted = true;
            afterRate = 0;
        }

        bool kinkValid = (_kink != 0 && _kink < 1e27);

        // General rule asserted:
        // - If the low-level call failed (setSlopes reverted) then kink must be invalid (==0 or >=1e27), and the observable rate must not have changed due to the call: i.e., either both before and after reverted, or both succeeded and returned equal values.
        // - If the low-level call succeeded then kink must be valid (0 < kink < 1e27).
        assert(
            callSucceeded ? (
                kinkValid
            ) : (
                (!kinkValid) && (
                    (beforeReverted && afterReverted) || (!beforeReverted && !afterReverted && afterRate == beforeRate)
                )
            )
        );
    }

    receive() external payable { }
}

