contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        // construct a SlopeData ABI-packed bytes to call setSlopes via the external function
        // prepare the SlopeData memory layout as in IVaultAdapter.SlopeData
        // We will attempt to call setSlopes and observe whether it reverts.

        // Build calldata for setSlopes(address, (uint256,uint256,uint256))
        bytes memory data = abi.encodeWithSelector(c.setSlopes.selector, asset, (kink, slope0, slope1));

        bool revertedSet;
        // call via low-level to catch revert without bubbling
        (bool ok, ) = address(c).call(data);
        revertedSet = !ok;

        // After attempting setSlopes, try calling rate (which can mutate utilizationData) and catch revert
        bool revertedRate;
        try c.rate(vault, asset) returns (uint256 latest) {
            revertedRate = false;
            // read latest to keep it in scope (though not used in assert directly)
            latest;
        } catch {
            revertedRate = true;
        }

        // The general invariant we assert:
        // If setSlopes did not revert then the provided kink must be in valid range (0 < kink < 1e27)
        // and calling rate must be allowed to execute (must not revert) for that asset/vault.
        // This encodes two expectations about successful setSlopes: it only succeeds for valid kink
        // and it does not put the contract into a state where rate immediately reverts for that asset.
        assert((revertedSet && (kink == 0 || kink >= 1e27)) || (!revertedSet && !revertedRate && kink > 0 && kink < 1e27));
    }

    receive() external payable { }
}

