contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will test that when setSlopes is called with a valid kink (0 < kink < 1e27),
    // the call does not revert and subsequent observable operations that rely on slopes
    // can be executed (we choose to call setLimits and then rate) — we assert that
    // either setSlopes reverted, or it succeeded and the subsequent rate call did not revert
    // and returned a value (i.e., execution reached the end). This encodes that valid
    // slopes inputs are accepted and the contract remains callable.

    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 maxMultiplier, uint256 minMultiplier, uint256 rateParam, uint256 amt) public payable {
        require(kink < 1e27);
        require(kink != 0);

        // Build SlopeData in memory encoding as in C.SlopeData (matches IVaultAdapter.SlopeData layout)
        // We cannot name that type here, so we will encode calldata for setSlopes via abi.encode
        bytes memory data = abi.encodeWithSelector(c.setSlopes.selector, asset, (abi.encodePacked(kink, slope0, slope1)));
        // But above can't be used to call external functions changing state in one shot; instead call setSlopes normally.
        bool setSlopesReverted;
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            setSlopesReverted = false;
        } catch {
            setSlopesReverted = true;
        }

        bool setLimitsReverted;
        try c.setLimits(maxMultiplier, minMultiplier, rateParam) {
            setLimitsReverted = false;
        } catch {
            setLimitsReverted = true;
        }

        bool rateReverted;
        uint256 latestAnswer = 0;
        try c.rate(vault, asset) returns (uint256 ans) {
            rateReverted = false;
            latestAnswer = ans;
        } catch {
            rateReverted = true;
        }

        // General rule (expressed as a single assert):
        // If setSlopes was called with a valid kink (precondition above) then it must not revert;
        // consequently, if setSlopes succeeded and setLimits succeeded, then calling rate must not revert.
        // We assert the logical relation among revert flags.
        assert( setSlopesReverted || (!setSlopesReverted && (setLimitsReverted == false ? rateReverted == false : true)) );
    }

    // Minimal receive to accept ETH if needed
    receive() external payable {}
 }
